with seed(standard_code,code,name,seq,required,classification,grade_code) as (values
('พ 1.1','HPE-P4-01','อธิบายการเจริญเติบโตและพัฒนาการของร่างกายและจิตใจตามวัย',1,true,'must_know','P4'),
('พ 1.1','HPE-P4-02','อธิบายความสำคัญของกล้ามเนื้อ กระดูกและข้อที่มีผลต่อสุขภาพการเจริญเติบโตและพัฒนาการ',2,true,'must_know','P4'),
('พ 1.1','HPE-P4-03','อธิบายวิธีดูแลกล้ามเนื้อ กระดูกและข้อให้ทำงานอย่างมีประสิทธิภาพ',3,true,'must_know','P4'),
('พ 2.1','HPE-P4-04','อธิบายคุณลักษณะของความเป็นเพื่อนและสมาชิกที่ดีของครอบครัว',4,false,'should_know','P4'),
('พ 2.1','HPE-P4-05','แสดงพฤติกรรมที่เหมาะสมกับเพศของตนตามวัฒนธรรมไทย',5,false,'should_know','P4'),
('พ 2.1','HPE-P4-06','ยกตัวอย่างวิธีการปฏิเสธการกระทำที่เป็นอันตรายและไม่เหมาะสมในเรื่องเพศ',6,true,'must_know','P4'),
('พ 3.1','HPE-P4-07','ควบคุมตนเองเมื่อใช้ทักษะการเคลื่อนไหวในลักษณะผสมผสานได้ทั้งแบบอยู่กับที่ เคลื่อนที่ และใช้อุปกรณ์ประกอบ',7,false,'should_know','P4'),
('พ 3.1','HPE-P4-08','ฝึกกายบริหารท่ามือเปล่าประกอบจังหวะ',8,false,'should_know','P4'),
('พ 3.1','HPE-P4-09','เล่นเกมเลียนแบบและกิจกรรมแบบผลัด',9,false,'should_know','P4'),
('พ 3.1','HPE-P4-10','เล่นกีฬาพื้นฐานอย่างน้อย ๑ ชนิด',10,true,'must_know','P4'),
('พ 3.2','HPE-P4-11','ออกกำลังกาย เล่นเกม และกีฬาที่ตนเองชอบและมีความสามารถในการวิเคราะห์ผลพัฒนาการของตนเองตามตัวอย่างและแบบปฏิบัติของผู้อื่น',11,true,'must_know','P4'),
('พ 3.2','HPE-P4-12','ปฏิบัติตามกฎ กติกาการเล่นกีฬา พื้นฐานตามชนิดกีฬาที่เล่น',12,false,'should_know','P4'),
('พ 4.1','HPE-P4-13','อธิบายความสัมพันธ์ระหว่างสิ่งแวดล้อมกับสุขภาพ',13,true,'must_know','P4'),
('พ 4.1','HPE-P4-14','อธิบายสภาวะอารมณ์ ความรู้สึกที่มีผลต่อสุขภาพ',14,true,'must_know','P4'),
('พ 4.1','HPE-P4-15','วิเคราะห์ข้อมูลบนฉลากอาหารและผลิตภัณฑ์สุขภาพ เพื่อการเลือกบริโภค',15,true,'must_know','P4'),
('พ 4.1','HPE-P4-16','ทดสอบและปรับปรุงสมรรถภาพทางกายตามผลการตรวจสอบสมรรถภาพทางกาย',16,true,'must_know','P4'),
('พ 4.1','HPE-P4-17','อธิบายความสำคัญของการใช้ยาและใช้ยาอย่างถูกวิธี',17,true,'must_know','P4'),
('พ 4.1','HPE-P4-18','แสดงวิธีปฐมพยาบาลเมื่อได้รับอันตรายจากการใช้ผิด สารเคมี แมลงสัตว์กัดต่อย และการบาดเจ็บจากการเล่นกีฬา',18,true,'must_know','P4'),
('พ 4.1','HPE-P4-19','วิเคราะห์ผลเสียของการสูบบุหรี่และการดื่มสุราที่มีต่อสุขภาพและการป้องกัน',19,true,'must_know','P4'),
('พ 1.1','HPE-P5-01','อธิบายความสำคัญของระบบย่อยอาหาร และระบบขับถ่ายที่มีผลต่อสุขภาพ การเจริญเติบโต และพัฒนาการ',1,false,'should_know','P5'),
('พ 1.1','HPE-P5-02','อธิบายวิธีดูแลระบบย่อยอาหารและระบบขับถ่ายให้ทำงานตามปกติ',2,true,'must_know','P5'),
('พ 2.1','HPE-P5-03','อธิบายการเปลี่ยนแปลงทางเพศและปฏิบัติตนได้เหมาะสม',3,false,'should_know','P5'),
('พ 2.1','HPE-P5-04','อธิบายความสำคัญของการมีครอบครัวที่อบอุ่นตามวัฒนธรรมไทย',4,true,'must_know','P5'),
('พ 2.1','HPE-P5-05','ระบุพฤติกรรมที่พึงประสงค์ และไม่พึงประสงค์ในการแก้ไขปัญหาความขัดแย้งในครอบครัวและกลุ่มเพื่อน',5,true,'must_know','P5'),
('พ 3.1','HPE-P5-06','จัดรูปแบบการเคลื่อนไหวแบบผสมผสาน และควบคุมตนเองเมื่อใช้ทักษะการเคลื่อนไหวตามแบบที่กำหนด',6,false,'should_know','P5'),
('พ 3.1','HPE-P5-07','เล่นเกมนำไปสู่กีฬาที่เลือกและกิจกรรมการเคลื่อนไหวแบบผลัด',7,false,'should_know','P5'),
('พ 3.1','HPE-P5-08','ควบคุมการเคลื่อนไหวในเรื่องการรับแรง การใช้แรง และความสมดุล',8,false,'should_know','P5'),
('พ 3.1','HPE-P5-09','แสดงทักษะกลไกในการปฏิบัติกิจกรรมทางกายและเล่นกีฬา',9,false,'should_know','P5'),
('พ 3.1','HPE-P5-10','เล่นกีฬาไทยและกีฬาสากล ประเภทบุคคลและประเภททีมอย่างละ ๑ ชนิด',10,true,'must_know','P5'),
('พ 3.1','HPE-P5-11','อธิบายหลักการ และเข้าร่วมกิจกรรมนันทนาการอย่างน้อย ๑ กิจกรรม',11,true,'must_know','P5'),
('พ 3.2','HPE-P5-12','ออกกำลังกายอย่างมีรูปแบบ เล่นเกมที่ใช้ทักษะการคิดและตัดสินใจ',12,true,'must_know','P5'),
('พ 3.2','HPE-P5-13','เล่นกีฬาที่ตนเองชอบอย่างสม่ำเสมอ โดยสร้างทางเลือกในวิธีปฏิบัติของตนเองอย่างหลากหลาย และมีน้ำใจนักกีฬา',13,false,'should_know','P5'),
('พ 3.2','HPE-P5-14','ปฏิบัติตามกฎ กติกาการเล่นเกม กีฬาไทยและกีฬาสากล ตามชนิดกีฬาที่เล่น',14,false,'should_know','P5'),
('พ 3.2','HPE-P5-15','ปฏิบัติตนตามสิทธิของตนเอง ไม่ละเมิดสิทธิผู้อื่นและยอมรับในความแตกต่างระหว่างบุคคลในการเล่นเกมและกีฬาไทยกีฬาสากล',15,false,'should_know','P5'),
('พ 4.1','HPE-P5-16','แสดงพฤติกรรมที่เห็นความสำคัญของการปฏิบัติตนตามสุขบัญญัติแห่งชาติ',16,false,'should_know','P5'),
('พ 4.1','HPE-P5-17','ค้นหาข้อมูลข่าวสารเพื่อใช้สร้างเสริมสุขภาพ',17,true,'must_know','P5'),
('พ 4.1','HPE-P5-18','วิเคราะห์สื่อโฆษณาในการตัดสินใจเลือกซื้ออาหารและผลิตภัณฑ์สุขภาพอย่างมีเหตุผล',18,false,'should_know','P5'),
('พ 4.1','HPE-P5-19','ปฏิบัติตนในการป้องกันโรคที่พบบ่อยในชีวิตประจำวัน',19,true,'must_know','P5'),
('พ 4.1','HPE-P5-20','ทดสอบและปรับปรุงสมรรถภาพทางกายตามผลการทดสอบสมรรถภาพทางกาย',20,false,'should_know','P5'),
('พ 5.1','HPE-P5-21','วิเคราะห์ปัจจัยที่มีอิทธิพลต่อการใช้สารเสพติด',21,true,'must_know','P5'),
('พ 5.1','HPE-P5-22','วิเคราะห์ผลกระทบของการใช้ยาและสารเสพติดที่มีผลต่อร่างกาย จิตใจ อารมณ์ สังคม และสติปัญญา',22,true,'must_know','P5'),
('พ 5.1','HPE-P5-23','ปฏิบัติตนเพื่อความปลอดภัยจากการใช้ยาและหลีกเลี่ยงสารเสพติด',23,true,'must_know','P5'),
('พ 5.1','HPE-P5-24','วิเคราะห์อิทธิพลของสื่อที่มีต่อพฤติกรรมสุขภาพ',24,true,'must_know','P5'),
('พ 5.1','HPE-P5-25','ปฏิบัติตนเพื่อป้องกันอันตรายจากการเล่นกีฬา',25,false,'should_know','P5')
)
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,s.code,s.name,null,s.seq,'active' from seed s join public.learning_subjects sub on sub.code='HEALTH-PE' join public.learning_skills sk on sk.subject_id=sub.id and sk.code='HEALTH-PE' join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no,updated_at=now();
